import UIKit

// Generated from assets/brand/dormouse/dormouse-v3.svg (static Dormouse), rendered at 28pt @2x/@3x.
// Embedded rather than bundled so it cannot go missing in a static-library Swift package.
enum MascotImage {
  static let x2 = ""
  static let x3 = ""
  /// 216px transparent render (72pt @3x) for the Commander avatar; same source art, palette-reduced.
  static let large = ""
}

extension MascotImage {
  /// The 216px Commander avatar, decoded once. Rendered at 72pt (scale 3).
  static let largeImage: UIImage? = Data(base64Encoded: large).flatMap { UIImage(data: $0, scale: 3) }
  /// The 28pt drawer icon.
  static let smallImage: UIImage? = (Data(base64Encoded: x3).flatMap { UIImage(data: $0, scale: 3) })
}
